query TX_ID_QUERY($offset: TransactionOffset!) {
  transactions(offset: $offset) {
    id
    protocolVersion
    raw
    hash
    unshieldedCreatedOutputs {
      owner
      intentHash
      tokenType
      value
      __typename
    }
    unshieldedSpentOutputs {
      owner
      intentHash
      tokenType
      value
      __typename
    }
    block {
      height
      hash
      author
      timestamp
      __typename
    }
    ... on RegularTransaction {
      identifiers
      fees {
        estimatedFees
        paidFees
        __typename
      }
      transactionResult {
        status
        segments {
          id
          success
          __typename
        }
        __typename
      }
      __typename
    }
    __typename
  }
}

query CONTRACT_STATE_QUERY($address: HexEncoded!, $offset: ContractActionOffset) {
  contractAction(address: $address, offset: $offset) {
    state
    __typename
  }
}

query QUERY_UNSHIELDED_BALANCES_WITH_OFFSET($address: HexEncoded!, $offset: ContractActionOffset) {
  contractAction(address: $address, offset: $offset) {
    ... on ContractDeploy {
      unshieldedBalances {
        tokenType
        amount
        __typename
      }
      __typename
    }
    ... on ContractUpdate {
      unshieldedBalances {
        tokenType
        amount
        __typename
      }
      __typename
    }
    ... on ContractCall {
      deploy {
        unshieldedBalances {
          tokenType
          amount
          __typename
        }
        __typename
      }
      __typename
    }
    __typename
  }
}

query CONTRACT_STATE_QUERY($address: HexEncoded!, $offset: ContractActionOffset) {
  contractAction(address: $address, offset: $offset) {
    state
    __typename
  }
}
